"""Stateful circuit execution: register cells and the cycle driver.

:mod:`src.k_circt.semantics` says what each operation *means*; this module holds
the state those rules read and write, and sequences a clock cycle:

1. seed ``<inputs>``/``<env>`` from the port values,
2. drain ``<k>`` with the combinational rules (registers read as ``<state>``),
3. run the sequential rules so every register stages its next value in
   ``<next>``,
4. fire :class:`~src.k_circt.semantics.ClockEdgeRule` to commit ``<next>`` into
   ``<state>`` and advance ``<cycle>``.

Steps 2 and 3 are deliberately separate: a register never observes another
register's post-edge value, which is what makes the counter in
``inputs/counter.mlir`` increment by exactly one per cycle.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Dict, Iterator, List, Optional, Sequence

from mlir.ir import Block, Operation, Trait, Value

from .configuration import KConfiguration
from .semantics import (
    CIRCUIT_RULES,
    RuleApplication,
    RuleEngine,
    RulePhase,
    RuleSet,
    SemanticError,
    register_key,
)

__all__ = [
    "RegisterCell",
    "CircuitState",
    "CycleResult",
    "StatefulCircuit",
    "execute_function",
]

#: Operations that own a hardware module body.
MODULE_OPS = ("hw.module", "hw.module.extern", "firrtl.module", "sv.module")


# ---------------------------------------------------------------------------
# Register state
# ---------------------------------------------------------------------------


@dataclass
class RegisterCell:
    """One register's state, as it appears in the ``<state>`` cell."""

    name: str
    width: int = 0
    value: int = 0
    next_value: Optional[int] = None
    reset_value: int = 0
    op: Optional[Operation] = None
    cycles_latched: int = 0

    def mask(self) -> int:
        return (1 << self.width) - 1 if self.width > 0 else 0

    def truncate(self, value: int) -> int:
        mask = self.mask()
        return int(value) & mask if mask else int(value)

    # -- two-phase update -------------------------------------------------
    def read(self) -> int:
        return self.value

    def write(self, value: int) -> int:
        self.value = self.truncate(value)
        return self.value

    def stage(self, value: int) -> int:
        self.next_value = self.truncate(value)
        return self.next_value

    def commit(self) -> int:
        if self.next_value is not None:
            self.value = self.next_value
            self.next_value = None
            self.cycles_latched += 1
        return self.value

    def reset(self) -> int:
        self.value = self.truncate(self.reset_value)
        self.next_value = None
        self.cycles_latched = 0
        return self.value

    def __str__(self) -> str:
        return f"{self.name} |-> {self.value} (i{self.width})"


class CircuitState:
    """The register state of one circuit, keyed by register name."""

    def __init__(self, cells: Optional[Sequence[RegisterCell]] = None) -> None:
        self.cells: Dict[str, RegisterCell] = {}
        for cell in cells or ():
            self.cells[cell.name] = cell

    # -- construction -----------------------------------------------------
    @classmethod
    def from_module(
        cls, module: Operation, rules: Optional[RuleSet] = None
    ) -> "CircuitState":
        """Discover every register in ``module``'s body.

        A "register" is any operation the rule set gives a *sequential* rule, so
        adding a stateful operation to the semantics automatically teaches the
        executor about it.
        """
        rule_set = rules if rules is not None else CIRCUIT_RULES
        cells: List[RegisterCell] = []
        for op in _body_operations(module):
            if not rule_set.rules_for(op.name, RulePhase.SEQUENTIAL):
                continue
            cells.append(
                RegisterCell(
                    name=register_key(op),
                    width=_width_of_op(op),
                    reset_value=_reset_value_of(op),
                    op=op,
                )
            )
        state = cls(cells)
        state.reset()
        return state

    # -- access -----------------------------------------------------------
    def cell(self, name: str) -> Optional[RegisterCell]:
        return self.cells.get(name)

    def read(self, name: str, default: int = 0) -> int:
        cell = self.cells.get(name)
        return cell.value if cell is not None else int(default)

    def write(self, name: str, value: int) -> int:
        cell = self.cells.get(name)
        if cell is None:
            cell = self.cells.setdefault(name, RegisterCell(name=name))
        return cell.write(value)

    def stage(self, name: str, value: int) -> int:
        cell = self.cells.get(name)
        if cell is None:
            cell = self.cells.setdefault(name, RegisterCell(name=name))
        return cell.stage(value)

    def commit(self) -> Dict[str, int]:
        return {name: cell.commit() for name, cell in self.cells.items()}

    def reset(self) -> Dict[str, int]:
        return {name: cell.reset() for name, cell in self.cells.items()}

    # -- views -------------------------------------------------------------
    def snapshot(self) -> Dict[str, int]:
        return {name: cell.value for name, cell in self.cells.items()}

    def names(self) -> List[str]:
        return list(self.cells)

    @property
    def registers(self) -> List[RegisterCell]:
        return list(self.cells.values())

    @property
    def is_stateful(self) -> bool:
        return bool(self.cells)

    # -- configuration interop --------------------------------------------
    def load_into(self, config: KConfiguration) -> KConfiguration:
        """Copy this state into a configuration's ``<state>`` cell."""
        config.state.clear()
        config.state.update(self.snapshot())
        return config

    def sync_from(self, config: KConfiguration) -> "CircuitState":
        """Adopt the values a rule left in ``<state>``."""
        for name, value in config.state.items():
            self.write(name, value)
        return self

    def __len__(self) -> int:
        return len(self.cells)

    def __iter__(self) -> Iterator[RegisterCell]:
        return iter(self.cells.values())

    def __contains__(self, name: str) -> bool:
        return name in self.cells

    def __str__(self) -> str:
        return " ".join(str(cell) for cell in self.cells.values()) or ".Map"

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"<CircuitState registers={list(self.cells)}>"


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def _body_operations(module: Operation) -> List[Operation]:
    if not module.regions or not module.regions[0].blocks:
        return []
    return list(module.regions[0].blocks[0].operations)


def _width_of_op(op: Operation) -> int:
    from circt.hw_dialect import bit_width_of

    for result in op.results:
        width = bit_width_of(result.type)
        if width:
            return width
    return int(getattr(op, "_declared_width", 0) or 0)


def _reset_value_of(op: Operation) -> int:
    """The register's power-on value.

    ``seq.compreg %next, %clk reset %reset, %c0_i8`` names its reset value with
    an operand, so the constant behind that operand is read directly - the reset
    value has to be known before any rule has settled the design.  The operand
    index comes from the dialect class (``seq.compreg.ce`` puts a clock enable
    before the reset pair), defaulting to CIRCT's plain-register layout.
    """
    declared = int(getattr(op, "reset_value", 0) or 0)
    index = int(getattr(op, "RESET_VALUE", 3))
    operands = op.operands
    if len(operands) <= index:
        return declared
    operand = operands[index]
    if not isinstance(operand, Value):
        return declared
    defining = operand.defining_op
    if defining is None:
        return declared
    attr = defining.attributes.get("value")
    if attr is None or not defining.has_trait(Trait.CONSTANT_LIKE):
        return declared
    try:
        return int(attr.value)
    except (TypeError, ValueError):  # pragma: no cover - defensive
        return declared


# ---------------------------------------------------------------------------
# Cycle results
# ---------------------------------------------------------------------------


@dataclass
class CycleResult:
    """Everything one clock cycle produced."""

    cycle: int
    inputs: Dict[str, int] = field(default_factory=dict)
    outputs: Dict[str, int] = field(default_factory=dict)
    registers: Dict[str, int] = field(default_factory=dict)
    next_registers: Dict[str, int] = field(default_factory=dict)
    applications: List[RuleApplication] = field(default_factory=list)

    @property
    def num_steps(self) -> int:
        return len(self.applications)

    def rule_names(self) -> List[str]:
        return [application.rule for application in self.applications]

    def output(self, name: Optional[str] = None, default: int = 0) -> int:
        if name is None:
            return next(iter(self.outputs.values()), default)
        return self.outputs.get(name, default)

    def __str__(self) -> str:
        parts = [f"cycle={self.cycle}"]
        for label, values in (
            ("in", self.inputs),
            ("state", self.registers),
            ("out", self.outputs),
        ):
            if values:
                rendered = ", ".join(f"{k}={v}" for k, v in sorted(values.items()))
                parts.append(f"{label}({rendered})")
        parts.append(f"steps={self.num_steps}")
        return " ".join(parts)


# ---------------------------------------------------------------------------
# Executor
# ---------------------------------------------------------------------------


class StatefulCircuit:
    """Executes an ``hw.module`` through the semantic rules, cycle by cycle."""

    def __init__(
        self,
        module: Operation,
        rules: Optional[RuleSet] = None,
        engine: Optional[RuleEngine] = None,
    ) -> None:
        if module.name not in MODULE_OPS:
            raise SemanticError(
                f"expected a hardware module operation, got '{module.name}'"
            )
        self.module = module
        self.rules = rules if rules is not None else CIRCUIT_RULES
        self.engine = engine if engine is not None else RuleEngine(self.rules)
        self.config = KConfiguration.initial()
        self.state = CircuitState.from_module(module, self.rules)

        self._body: List[Operation] = _body_operations(module)
        self._ports = list(getattr(module, "ports", []) or [])
        self._input_ports = [p for p in self._ports if not p.is_output]
        self._output_ports = [p for p in self._ports if p.is_output]
        self._registers = [
            cell.op for cell in self.state.registers if cell.op is not None
        ]
        self.inputs: Dict[str, int] = {p.name: 0 for p in self._input_ports}
        self.reset()

    # -- structure --------------------------------------------------------
    @property
    def ports(self) -> List[Any]:
        return list(self._ports)

    @property
    def input_names(self) -> List[str]:
        return [p.name for p in self._input_ports]

    @property
    def output_names(self) -> List[str]:
        return [p.name for p in self._output_ports]

    @property
    def body(self) -> List[Operation]:
        return list(self._body)

    @property
    def registers(self) -> List[RegisterCell]:
        return self.state.registers

    @property
    def is_sequential(self) -> bool:
        return self.state.is_stateful

    @property
    def cycle(self) -> int:
        return self.config.cycle

    # -- lifecycle --------------------------------------------------------
    def reset(self) -> "StatefulCircuit":
        """Assert reset: clear the configuration and re-seed register state."""
        self.config.reset()
        self.state.reset()
        self.state.load_into(self.config)
        self.engine.reset()
        return self

    def set_input(self, name: str, value: int) -> None:
        if name not in self.inputs:
            raise SemanticError(f"'{name}' is not an input port of this module")
        self.inputs[name] = int(value)

    def set_inputs(self, values: Optional[Dict[str, int]]) -> None:
        for name, value in (values or {}).items():
            self.set_input(name, value)

    # -- phase 1: combinational settle ------------------------------------
    def settle(
        self, inputs: Optional[Dict[str, int]] = None
    ) -> List[RuleApplication]:
        """Bind the ports, then drain ``<k>`` with the combinational rules."""
        self.set_inputs(inputs)
        self._seed_environment()
        return self.engine.settle(self.config, self._body)

    def _seed_environment(self) -> None:
        config = self.config
        config.cell("env").clear()
        config.cell("outputs").clear()
        config.inputs.clear()
        config.inputs.update(self.inputs)
        self.state.load_into(config)

        block = self._entry_block()
        if block is None:
            return
        for index, argument in enumerate(block.arguments):
            name = (
                self._input_ports[index].name
                if index < len(self._input_ports)
                else (argument.name or f"arg{index}")
            )
            value = int(self.inputs.get(name, 0))
            config.bind(argument, value)
            if name:
                config.bind(name, value)

    def _entry_block(self) -> Optional[Block]:
        if not self.module.regions or not self.module.regions[0].blocks:
            return None
        return self.module.regions[0].blocks[0]

    # -- phase 2: clock edge ----------------------------------------------
    def step(self, inputs: Optional[Dict[str, int]] = None) -> CycleResult:
        """Advance one clock cycle and report what happened."""
        applications = list(self.settle(inputs))
        before = self.state.snapshot()
        outputs = dict(self.config.outputs)

        applications.extend(self.engine.latch(self.config, self._registers))
        staged = dict(self.config.next_state)
        cycle = self.config.cycle
        applications.append(self.engine.clock_edge(self.config))
        self.state.sync_from(self.config)

        return CycleResult(
            cycle=cycle,
            inputs=dict(self.inputs),
            outputs=outputs,
            registers=before,
            next_registers=staged,
            applications=applications,
        )

    def run(
        self,
        cycles: int,
        inputs: Optional[Dict[str, int]] = None,
        stimulus: Optional[Sequence[Dict[str, int]]] = None,
    ) -> List[CycleResult]:
        """Run ``cycles`` clock cycles, returning one result per cycle."""
        self.set_inputs(inputs)
        results: List[CycleResult] = []
        for index in range(max(0, cycles)):
            override = None
            if stimulus is not None and index < len(stimulus):
                override = stimulus[index]
            results.append(self.step(override))
        return results

    # -- reading results --------------------------------------------------
    def evaluate(self, inputs: Optional[Dict[str, int]] = None) -> Dict[str, int]:
        """Settle without a clock edge and return the module outputs."""
        self.settle(inputs)
        return dict(self.config.outputs)

    def output(self, name: Optional[str] = None, default: int = 0) -> int:
        outputs = self.config.outputs
        if name is None:
            return next(iter(outputs.values()), default)
        if name not in outputs:
            raise SemanticError(f"'{name}' is not an output port of this module")
        return outputs[name]

    def output_after(
        self,
        cycles: int,
        inputs: Optional[Dict[str, int]] = None,
        name: Optional[str] = None,
    ) -> int:
        """Run ``cycles`` cycles, settle once more, then read an output."""
        self.run(cycles, inputs)
        self.settle()
        return self.output(name)

    def register_values(self) -> Dict[str, int]:
        return self.state.snapshot()

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        symbol = self.module.attributes.get("sym_name")
        label = symbol.value if symbol is not None else "?"
        return (
            f"<StatefulCircuit @{label} ports={len(self._ports)} "
            f"registers={len(self.state)} cycle={self.cycle}>"
        )


# ---------------------------------------------------------------------------
# Functional (arith / func) execution
# ---------------------------------------------------------------------------


def execute_function(
    func: Operation,
    arguments: Optional[Sequence[int]] = None,
    rules: Optional[RuleSet] = None,
) -> Dict[str, int]:
    """Evaluate a single-block ``func.func`` body through the same rules.

    This is what connects the semantic layer back to the MLIR sample input: the
    ``arith`` rules in :mod:`src.k_circt.semantics` evaluate ``@fold_chain``
    without the circuit machinery being involved at all.
    """
    if func.name not in ("func.func", "builtin.func"):
        raise SemanticError(f"expected a function operation, got '{func.name}'")
    if not func.regions or not func.regions[0].blocks:
        return {}

    engine = RuleEngine(rules if rules is not None else CIRCUIT_RULES)
    config = KConfiguration.initial()
    block = func.regions[0].blocks[0]

    supplied = list(arguments or ())
    for index, argument in enumerate(block.arguments):
        value = supplied[index] if index < len(supplied) else 0
        config.bind(argument, int(value))
        if argument.name:
            config.bind(argument.name, int(value))

    config.enqueue_all(list(block.operations))
    engine.run(config, RulePhase.FUNCTIONAL)
    return dict(config.outputs)

"""K-style configurations: the nested cells a semantic rule rewrites.

The K framework describes a language by giving a *configuration* - a nested bag
of named cells - and a set of rewrite rules that transform it.  This module
provides the configuration half of that picture for the circuit semantics in
:mod:`src.k_circt.semantics`::

    <T>
      <k>        the continuation: operations still to be evaluated
      <env>      SSA values / signal names bound to integers
      <state>    the value each register currently holds
      <next>     the value each register will latch at the coming clock edge
      <inputs>   the module's input port values for this cycle
      <outputs>  the module's output port values, once <k> has drained
      <cycle>    the clock cycle number
      <steps>    how many rules have fired
    </T>

Cells are plain Python containers rather than terms, but the discipline is the
same: a rule reads and writes cells and nothing else, so the whole state of an
evaluation is visible in one place and can be snapshotted for a trace.
"""
from __future__ import annotations

from typing import Any, Callable, Dict, Iterator, List, Optional, Sequence

__all__ = [
    "Cell",
    "CellName",
    "KConfiguration",
    "ConfigurationError",
]


class ConfigurationError(Exception):
    """Raised when a cell is missing or holds the wrong kind of value."""


class CellName:
    """The cell names used by the circuit semantics."""

    K = "k"
    ENV = "env"
    STATE = "state"
    NEXT = "next"
    INPUTS = "inputs"
    OUTPUTS = "outputs"
    CYCLE = "cycle"
    STEPS = "steps"
    SYMBOLS = "symbols"
    TYPES = "types"

    #: Declaration order, which is also the order cells are rendered in.
    ORDER = (K, ENV, STATE, NEXT, INPUTS, OUTPUTS, CYCLE, STEPS, SYMBOLS, TYPES)


class Cell:
    """One named slot of a configuration.

    A cell remembers the factory that produced its initial contents so that
    :meth:`reset` can restore it without the caller having to know whether it
    holds a list, a dict or an integer.
    """

    __slots__ = ("name", "_value", "_factory")

    def __init__(
        self,
        name: str,
        value: Any = None,
        factory: Optional[Callable[[], Any]] = None,
    ) -> None:
        self.name = name
        self._factory = factory
        self._value = value if factory is None else (value if value is not None else factory())

    # -- contents ---------------------------------------------------------
    @property
    def value(self) -> Any:
        return self._value

    @value.setter
    def value(self, new_value: Any) -> None:
        self._value = new_value

    def get(self) -> Any:
        return self._value

    def set(self, new_value: Any) -> Any:
        self._value = new_value
        return self._value

    def reset(self) -> Any:
        """Restore the initial contents (a fresh container, not the old one)."""
        self._value = self._factory() if self._factory is not None else None
        return self._value

    def clear(self) -> None:
        if isinstance(self._value, (list, dict, set)):
            self._value.clear()
        else:
            self.reset()

    def copy(self) -> "Cell":
        value = self._value
        if isinstance(value, dict):
            value = dict(value)
        elif isinstance(value, list):
            value = list(value)
        elif isinstance(value, set):
            value = set(value)
        return Cell(self.name, value, self._factory)

    # -- rendering --------------------------------------------------------
    def __len__(self) -> int:
        try:
            return len(self._value)
        except TypeError:
            return 0

    def __bool__(self) -> bool:
        return bool(self._value)

    def __iter__(self) -> Iterator[Any]:
        return iter(self._value)

    def __str__(self) -> str:
        return f"<{self.name}> {_render(self._value)} </{self.name}>"

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"Cell({self.name!r}, {self._value!r})"


def _render(value: Any) -> str:
    """Render cell contents the way K prints a term."""
    if isinstance(value, dict):
        if not value:
            return ".Map"
        return " ".join(f"{_key(k)} |-> {v}" for k, v in value.items())
    if isinstance(value, (list, tuple)):
        if not value:
            return ".K"
        return " ~> ".join(_key(item) for item in value)
    return str(value)


def _key(item: Any) -> str:
    """A short, stable label for an environment key or continuation item."""
    name = getattr(item, "name", None)
    if isinstance(name, str) and name:
        return name
    if isinstance(item, str):
        return item
    return repr(item)


class KConfiguration:
    """An ordered bag of :class:`Cell` objects.

    Cells are reachable both by attribute (``config.env``) and by subscript
    (``config["env"]``); the attribute form returns the *contents* so rules read
    naturally, while :meth:`cell` returns the cell object itself.
    """

    def __init__(self, cells: Optional[Sequence[Cell]] = None) -> None:
        self._cells: Dict[str, Cell] = {}
        for cell in cells or ():
            self.add_cell(cell)

    # -- construction -----------------------------------------------------
    @classmethod
    def initial(cls) -> "KConfiguration":
        """The configuration a circuit evaluation starts from."""
        return cls(
            [
                Cell(CellName.K, factory=list),
                Cell(CellName.ENV, factory=dict),
                Cell(CellName.STATE, factory=dict),
                Cell(CellName.NEXT, factory=dict),
                Cell(CellName.INPUTS, factory=dict),
                Cell(CellName.OUTPUTS, factory=dict),
                Cell(CellName.CYCLE, factory=int),
                Cell(CellName.STEPS, factory=int),
            ]
        )

    def add_cell(self, cell: Cell) -> Cell:
        self._cells[cell.name] = cell
        return cell

    def declare(self, name: str, factory: Optional[Callable[[], Any]] = None) -> Cell:
        """Add a cell if it is not already present and return it."""
        existing = self._cells.get(name)
        if existing is not None:
            return existing
        return self.add_cell(Cell(name, factory=factory))

    # -- access -----------------------------------------------------------
    def cell(self, name: str) -> Cell:
        try:
            return self._cells[name]
        except KeyError:
            raise ConfigurationError(f"no <{name}> cell in this configuration") from None

    def has_cell(self, name: str) -> bool:
        return name in self._cells

    @property
    def cells(self) -> Dict[str, Cell]:
        return dict(self._cells)

    def cell_names(self) -> List[str]:
        ordered = [n for n in CellName.ORDER if n in self._cells]
        extra = [n for n in self._cells if n not in ordered]
        return ordered + extra

    def __getitem__(self, name: str) -> Any:
        return self.cell(name).value

    def __setitem__(self, name: str, value: Any) -> None:
        self.declare(name).set(value)

    def __contains__(self, name: str) -> bool:
        return name in self._cells

    def __getattr__(self, name: str) -> Any:
        # Only reached when normal attribute lookup fails, so ``self._cells`` is
        # already in ``__dict__`` and this cannot recurse.
        cells = self.__dict__.get("_cells", {})
        if name in cells:
            return cells[name].value
        raise AttributeError(name)

    # -- convenience for rules --------------------------------------------
    @property
    def k(self) -> List[Any]:
        return self.cell(CellName.K).value

    @property
    def env(self) -> Dict[Any, int]:
        return self.cell(CellName.ENV).value

    @property
    def state(self) -> Dict[str, int]:
        return self.cell(CellName.STATE).value

    @property
    def next_state(self) -> Dict[str, int]:
        return self.cell(CellName.NEXT).value

    @property
    def inputs(self) -> Dict[str, int]:
        return self.cell(CellName.INPUTS).value

    @property
    def outputs(self) -> Dict[str, int]:
        return self.cell(CellName.OUTPUTS).value

    @property
    def cycle(self) -> int:
        return self.cell(CellName.CYCLE).value

    @cycle.setter
    def cycle(self, value: int) -> None:
        self.cell(CellName.CYCLE).set(int(value))

    @property
    def steps(self) -> int:
        return self.cell(CellName.STEPS).value

    def count_step(self, amount: int = 1) -> int:
        cell = self.cell(CellName.STEPS)
        cell.set(cell.value + amount)
        return cell.value

    # -- <k> continuation --------------------------------------------------
    def enqueue(self, item: Any) -> None:
        self.k.append(item)

    def enqueue_all(self, items: Sequence[Any]) -> None:
        self.k.extend(items)

    def dequeue(self) -> Any:
        queue = self.k
        return queue.pop(0) if queue else None

    def requeue(self, item: Any) -> None:
        """Send ``item`` to the back of the continuation (it was stuck)."""
        self.k.append(item)

    @property
    def is_empty(self) -> bool:
        return not self.k

    # -- <env> bindings ----------------------------------------------------
    def bind(self, key: Any, value: int) -> int:
        self.env[key] = int(value)
        return int(value)

    def lookup(self, key: Any, default: Optional[int] = None) -> Optional[int]:
        env = self.env
        if key in env:
            return env[key]
        name = getattr(key, "name", None)
        if isinstance(name, str) and name in env:
            return env[name]
        return default

    def is_bound(self, key: Any) -> bool:
        return self.lookup(key) is not None

    # -- snapshots ---------------------------------------------------------
    def snapshot(self) -> "KConfiguration":
        """A shallow copy deep enough that later rules cannot mutate it."""
        return KConfiguration([cell.copy() for cell in self._cells.values()])

    def reset(self) -> "KConfiguration":
        for cell in self._cells.values():
            cell.reset()
        return self

    # -- rendering ---------------------------------------------------------
    def to_text(self, indent: str = "  ") -> str:
        lines = ["<T>"]
        for name in self.cell_names():
            lines.append(indent + str(self._cells[name]))
        lines.append("</T>")
        return "\n".join(lines)

    def __str__(self) -> str:
        return self.to_text()

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"<KConfiguration cells={self.cell_names()}>"

# ---------------------------------------------------------------------------
# Rule sets
# ---------------------------------------------------------------------------


class RuleSet:
    """An indexed, priority-ordered collection of rules."""

    def __init__(self, rules: Optional[Sequence[SemanticRule]] = None) -> None:
        self._rules: List[SemanticRule] = []
        self._by_op: Dict[str, List[SemanticRule]] = {}
        for rule in rules or ():
            self.add(rule)

    # -- construction -----------------------------------------------------
    def add(self, rule: SemanticRule) -> "RuleSet":
        self._rules.append(rule)
        for op_name in rule.OP_NAMES:
            bucket = self._by_op.setdefault(op_name, [])
            bucket.append(rule)
            bucket.sort(key=lambda r: -r.PRIORITY)
        return self

    def extend(self, rules: Sequence[SemanticRule]) -> "RuleSet":
        for rule in rules:
            self.add(rule)
        return self

    # -- queries ----------------------------------------------------------
    @property
    def rules(self) -> List[SemanticRule]:
        return list(self._rules)

    def names(self) -> List[str]:
        return [rule.NAME for rule in self._rules]

    def op_names(self) -> List[str]:
        return sorted(self._by_op)

    def rules_for(
        self, op_name: str, phase: Optional[RulePhase] = None
    ) -> List[SemanticRule]:
        candidates = self._by_op.get(op_name, [])
        if phase is None:
            return list(candidates)
        return [rule for rule in candidates if rule.PHASE is phase]

    def for_phase(self, phase: RulePhase) -> "RuleSet":
        return RuleSet([rule for rule in self._rules if rule.PHASE is phase])

    def find(
        self,
        op: Operation,
        config: KConfiguration,
        phase: Optional[RulePhase] = None,
    ) -> Optional[SemanticRule]:
        """The highest-priority rule that matches ``op`` in ``phase``."""
        for rule in self.rules_for(op.name, phase):
            if rule.matches(op, config):
                return rule
        return None

    def named(self, name: str) -> Optional[SemanticRule]:
        for rule in self._rules:
            if rule.NAME == name:
                return rule
        return None

    def handles(self, op_name: str) -> bool:
        return op_name in self._by_op

    def __len__(self) -> int:
        return len(self._rules)

    def __iter__(self) -> Iterator[SemanticRule]:
        return iter(self._rules)

    def to_text(self) -> str:
        return "\n".join(rule.describe() for rule in self._rules)

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"<RuleSet rules={len(self._rules)} ops={len(self._by_op)}>"


def circuit_rules() -> RuleSet:
    """The default rule set: ``hw`` + ``comb`` + ``seq`` + ``arith``/``func``."""
    return RuleSet(
        [
            # hw
            HWConstantRule(),
            HWWireRule(),
            HWOutputRule(),
            # comb
            CombAddRule(),
            CombSubRule(),
            CombMulRule(),
            CombAndRule(),
